namespace Api.Web.FinanceIA.Models.Financia;

/// <summary>
/// EF Core entity that maps to [dbo].[Alerts].
/// Represents a risk or informational alert generated by the analysis engine.
/// </summary>
public sealed class Alert
{
    /// <summary>Primary key.</summary>
    public Guid AlertId { get; set; }

    /// <summary>Tenant that owns this alert.</summary>
    public string TenantId { get; set; } = string.Empty;

    /// <summary>Entity (PyME) related to this alert. Null for system-level alerts.</summary>
    public Guid? EntityId { get; set; }

    /// <summary>Analysis that generated this alert. Null for system-level alerts.</summary>
    public Guid? AnalysisId { get; set; }

    /// <summary>Alert type code (e.g. HIGH_LEVERAGE, TAX_DEBT_AFIP).</summary>
    public string AlertType { get; set; } = string.Empty;

    /// <summary>Severity level: Critical | High | Medium | Low.</summary>
    public string Severity { get; set; } = string.Empty;

    /// <summary>Human-readable alert title.</summary>
    public string Title { get; set; } = string.Empty;

    /// <summary>Detailed description of the alert condition.</summary>
    public string Description { get; set; } = string.Empty;

    /// <summary>Financial metric key that triggered the alert (e.g. debt_ratio). Null when not metric-based.</summary>
    public string? MetricKey { get; set; }

    /// <summary>Current value of the metric. Null when not metric-based.</summary>
    public decimal? MetricValue { get; set; }

    /// <summary>Threshold that was exceeded. Null when not metric-based.</summary>
    public decimal? ThresholdValue { get; set; }

    /// <summary>Whether the alert has been read by a user.</summary>
    public bool IsRead { get; set; }

    /// <summary>User who marked the alert as read.</summary>
    public Guid? ReadBy { get; set; }

    /// <summary>UTC timestamp when the alert was marked as read.</summary>
    public DateTime? ReadAt { get; set; }

    /// <summary>Whether the alert condition has been resolved.</summary>
    public bool IsResolved { get; set; }

    /// <summary>User who resolved the alert.</summary>
    public Guid? ResolvedBy { get; set; }

    /// <summary>UTC timestamp when the alert was resolved.</summary>
    public DateTime? ResolvedAt { get; set; }

    /// <summary>UTC timestamp when the alert was created.</summary>
    public DateTime CreatedAt { get; set; }
}
